package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"os"
	"reflect"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run script.go <source_file_name> <struct_name>")
		os.Exit(1)
	}

	sourceFileName := os.Args[1]
	structName := os.Args[2]

	fileContent, err := ioutil.ReadFile(sourceFileName)
	if err != nil {
		fmt.Printf("Error reading file: %s\n", err.Error())
		return
	}

	parsedTree, err := parser.ParseFile(token.NewFileSet(), "", string(fileContent), parser.ParseComments|parser.ParseStruct)
	if err != nil {
		fmt.Printf("Error parsing file: %s\n", err.Error())
		return
	}

	ast.Inspect(parsedTree, func(node ast.Node) bool {
		switch node.(type) {
		case *ast.StructType:
			structNode := node.(*ast.StructType)
			structFields := make([]reflect.StructField, len(structNode.Fields))

			for i, field := range structNode.Fields {
				structFields[i] = reflect.StructField{
					Name:   field.Names[0].Text(),
					Type:   reflect.TypeOf(field.Type),
					Comment: field.Comment,
				}
			}

			structType := reflect.TypeOf(structName).Elem()
			avroSchema, _ := json.MarshalIndent(reflect.StructTag{}.New(structType, structFields), "", "  ")

			err := ioutil.WriteFile(fmt.Sprintf("%s.avsc", structName), []byte(avroSchema), 0644)
			if err != nil {
				fmt.Printf("Error writing Avro schema: %s\n", err.Error())
			} else {
				fmt.Printf("Avro schema generated successfully for struct: %s.avsc\n", structName)
			}

			return false
		default:
			return true
		}
	})
}
